from typing import List

class Solution:
    def rankTeams(self, votes: List[str]) -> str:
        if not votes:
            return ""

        n = len(votes[0])
        teams = list(set(votes[0]))
        count = {team: [0] * n for team in teams}

        for vote in votes:
            for i, team in enumerate(vote):
                count[team][i] += 1

        teams.sort(key=lambda team: ([-count[team][i] for i in range(n)] + [team]))

        return "".join(teams)
